sys_script_include.script:
var DoctorUtilsClient = Class.create();
DoctorUtilsClient.prototype = Object.extendsObject(AbstractAjaxProcessor, {
    getDoctorDetails: function () {
        var doctor = new GlideRecord('u_doctor');
        if (doctor.get(this.getParameter('sysparm_doctor_id'))) {
            return JSON.stringify({
                first_name: doctor.getValue('u_first_name'),
                last_name: doctor.getValue('u_last_name'),
                specialization: doctor.getValue('u_specialization')
            });
        }
        return JSON.stringify({error: "Doctor not found"});
    }
});
